def p(s):return '<p>'+s+'</p>'
def steps(items):return '<ol>'+''.join('<li>'+s+'</li>' for s in items)+'</ol>'
def task(title,items):return '<div class="task"><h4>'+title+'</h4>'+steps(items)+'</div>'
def detail(title,body):return '<details open><summary><h3>'+title+'</h3></summary>'+body+'</details>'
def fill(s):return '<p class="pending">[[FILL: '+s+']]</p>'
