 address=('<a class="button" href="'+escape(url,quote=True)+'">Address · '+escape(title)+' ↗</a><p class="address">'+escape(url)+'</p>') if url else '<a class="button" href="#accounts">Address · find your personal link</a>'+fill('personal '+title+' link; do not publish a guessed address')
 content='<section class="svc" id="'+key+'" data-service="'+key+'" data-summary="'+escape(summary,quote=True)+'"><p class="eyebrow">Your services · '+str(len(services)+1).zfill(2)+'</p><div class="service-heading"><span class="icon" aria-hidden="true">'+icon+'</span><h2>'+title+'</h2></div>'+address+'<h3>What it is</h3>'+p(what)+access+extra+'<h3>Set it up · first time</h3>'+steps(setup)+detail('How to use it',tasks)+detail('On your devices',devices)+detail('If something’s wrong',steps(problems)+p('Still stuck? '+contact+'.'))+'<h3>Please don’t</h3>'+p(rules)+'<p class="back"><a href="#contents">Back to the guide contents</a></p></section>'
 services.append((key,title,content))
